                    & $trashBin $resolvedPath *> $null
                    if (($LASTEXITCODE -eq 0) -and -not (Microsoft.PowerShell.Management\Test-Path -LiteralPath $resolvedPath)) {
                        $movedByBinary = $true
                    }
